SMALL_ALPHABET = "ᴀʙᴄᴅᴇғɢʜɪᴊᴋʟᴍɴᴏᴘǫʀsᴛᴜᴠᴡxʏᴢ"
SMALL_TABLE = str.maketrans({
    **dict(zip("abcdefghijklmnopqrstuvwxyz", SMALL_ALPHABET)),
    **dict(zip("ABCDEFGHIJKLMNOPQRSTUVWXYZ", SMALL_ALPHABET)),
})
NORMAL_TABLE = str.maketrans(dict(zip(SMALL_ALPHABET, "abcdefghijklmnopqrstuvwxyz")))
MENU = {
    "post": "Make Post", "balance": "My Balance", "refer": "Reffer",
    "bonus": "Bonus", "redeem": "Redeem", "contact": "Contact Owner",
    "owner": "Owner Panel",
}


class UserError(Exception):
    pass


def scrub(value):
    result = re.sub(r"\b\d{6,}:[A-Za-z0-9_-]{20,}\b", "<BOT_TOKEN>", str(value))
    if TOKEN and TOKEN != "PASTE_BOT_TOKEN_HERE":
        result = result.replace(TOKEN, "<BOT_TOKEN>")
    return result


class SecretFilter(logging.Filter):
    def filter(self, record):
        record.msg, record.args = scrub(record.getMessage()), ()
        return True


def setup_logging():
    handler = logging.StreamHandler()
    handler.addFilter(SecretFilter())
    handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s: %(message)s"))
    logging.basicConfig(level=logging.INFO, handlers=[handler], force=True)
    telebot.logger.handlers.clear()
    telebot.logger.propagate = True
    telebot.logger.setLevel(logging.WARNING)


def log_error(where, error):
    LOG.warning("%s: %s: %s", where, type(error).__name__, scrub(error))


def user_lock(chat_id, user_id):
    with USER_LOCKS_GUARD:
        return USER_LOCKS.setdefault((chat_id, user_id), threading.RLock())


def atomic_write(path, contents):
    path = Path(path)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o600
    fd, temporary = tempfile.mkstemp(prefix=path.name + ".", dir=path.parent)
    try:
        os.fchmod(fd, mode)
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            stream.write(contents)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    finally:
        with contextlib.suppress(FileNotFoundError):
            os.unlink(temporary)


def read_json(path, default):
    if not path.exists():
        return default
    with path.open(encoding="utf-8-sig") as stream:
        return json.load(stream)


def u16(text):
    return len(text.encode("utf-16-le")) // 2


def entity_dicts(items):
    result = []
    for item in items or []:
        value = copy.deepcopy(item if isinstance(item, dict) else item.to_dict())
        value = {key: val for key, val in value.items() if val is not None}
        if "custom_emoji_id" in value:
            value["custom_emoji_id"] = str(value["custom_emoji_id"])
        result.append(value)
    return result


def entity_objects(items):
    return [types.MessageEntity.de_json(item) for item in entity_dicts(items)]


def valid_entities(text, entities):
    boundaries, offset = {0}, 0
    for character in text:
        offset += u16(character)
        boundaries.add(offset)
    for item in entity_dicts(entities):
        start, length = int(item["offset"]), int(item["length"])
        if length <= 0 or start not in boundaries or start + length not in boundaries:
            raise UserError("Invalid formatting. Please resend the text.")


def normal_label(text):
    return " ".join(emoji.replace_emoji(text or "", replace="").translate(NORMAL_TABLE).lower().split())


def protected_ranges(text, entities):
    protected = [
        (item["offset"], item["offset"] + item["length"])
        for item in entity_dicts(entities)
        if item["type"] in {"code", "pre", "url", "email", "custom_emoji", "mention", "bot_command"}
    ]
    for match in re.finditer(r"https?://\S+|tg://\S+|(?<!\w)/[A-Za-z][A-Za-z0-9_]*|@[A-Za-z0-9_]+", text):
        protected.append((u16(text[:match.start()]), u16(text[:match.end()])))
    return protected


def smallcaps(text, entities=()):
    protected = protected_ranges(text, entities)
    result, offset = [], 0
    for character in text:
        length = u16(character)
        keep = any(offset < end and offset + length > start for start, end in protected)
        result.append(character if keep else character.translate(SMALL_TABLE))
        offset += length
    return "".join(result)


def good_url(text):
    text = text.strip()
    if text.startswith(("t.me/", "telegram.me/")):
        text = "https://" + text
    parsed = urlparse(text)
    if any(char.isspace() for char in text):
        raise UserError("Send one URL without spaces.")
    if parsed.scheme in {"http", "https"} and parsed.netloc:
        return text
    if parsed.scheme == "tg" and (parsed.netloc or parsed.path):
        return text
    raise UserError("Use a valid https://, http:// or tg:// URL.")


def forwarded_chat(message):
    origin = getattr(message, "forward_origin", None)
    if origin:
        chat = getattr(origin, "chat", None) or getattr(origin, "sender_chat", None)
        if chat:
            return chat
    legacy = (getattr(message, "json", {}) or {}).get("forward_from_chat")
    return types.Chat.de_json(legacy) if legacy else None


class Storage:
    def __init__(self, folder):
        self.folder = Path(folder)
        self.folder.mkdir(parents=True, exist_ok=True)
        self.path = self.folder / "bot.db"
        self.users_file = self.folder / "users.json"
        self.redeem_file = self.folder / "redeem.txt"
        self.posts_file = self.folder / "posts.json"
        self.io_lock = threading.RLock()
        original = read_json(self.users_file, [])
        if not isinstance(original, list):
            raise RuntimeError("users.json is not a list; file left unchanged.")
        self.known_ids = {int(value) for value in original}
        self.initialize()

    @contextlib.contextmanager
    def db(self):
        connection = sqlite3.connect(str(self.path), timeout=30)
        connection.row_factory = sqlite3.Row
        connection.execute("PRAGMA busy_timeout=30000")
        try:
            connection.execute("BEGIN IMMEDIATE")
            yield connection
            connection.commit()
        except Exception:
            connection.rollback()
            raise
        finally:
            connection.close()

    def initialize(self):
        existed = self.path.exists()
        connection = sqlite3.connect(str(self.path), timeout=30)
        try:
            migrated = connection.execute("SELECT 1 FROM sqlite_master WHERE name='nxt_meta' AND type='table'").fetchone()
            if existed and not migrated:
                stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
                backup = sqlite3.connect(str(self.folder / f"bot.db.before-update-{stamp}.bak"))
                try:
                    connection.backup(backup)
                finally:
                    backup.close()
                LOG.info("Created pre-migration SQLite backup.")
            connection.execute("PRAGMA journal_mode=WAL")
        finally:
            connection.close()
        with self.db() as connection:
            connection.execute("""CREATE TABLE IF NOT EXISTS users (
                user_id INTEGER PRIMARY KEY, username TEXT, referrer INTEGER,
                balance INTEGER DEFAULT 0, last_bonus INTEGER DEFAULT 0,
                access_expiry INTEGER DEFAULT 0)""")
            columns = {row["name"] for row in connection.execute("PRAGMA table_info(users)")}
            for name, declaration in {
                "username": "TEXT", "referrer": "INTEGER", "balance": "INTEGER DEFAULT 0",
                "last_bonus": "INTEGER DEFAULT 0", "access_expiry": "INTEGER DEFAULT 0",
            }.items():
                if name not in columns:
                    connection.execute(f"ALTER TABLE users ADD COLUMN {name} {declaration}")
            for statement in [
                "CREATE TABLE IF NOT EXISTS nxt_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL)",
                "CREATE TABLE IF NOT EXISTS nxt_referral_rewards (joined_user INTEGER PRIMARY KEY, rewarded_at INTEGER NOT NULL)",
                "CREATE TABLE IF NOT EXISTS nxt_redeem_codes (code TEXT PRIMARY KEY, amount INTEGER NOT NULL, max_uses INTEGER NOT NULL, used INTEGER NOT NULL, expires INTEGER NOT NULL)",
                "CREATE TABLE IF NOT EXISTS nxt_redeem_claims (code TEXT NOT NULL, user_id INTEGER NOT NULL, claimed_at INTEGER NOT NULL, PRIMARY KEY(code,user_id))",
                "CREATE TABLE IF NOT EXISTS nxt_posts (id TEXT PRIMARY KEY, owner_id INTEGER, chat_id INTEGER, data_json TEXT NOT NULL, created_at INTEGER NOT NULL)",
                "CREATE TABLE IF NOT EXISTS nxt_workflows (chat_id INTEGER NOT NULL, user_id INTEGER NOT NULL, stage TEXT NOT NULL, data_json TEXT NOT NULL, prompt_id INTEGER, PRIMARY KEY(chat_id,user_id))",
            ]:
                connection.execute(statement)
            if not connection.execute("SELECT 1 FROM nxt_meta WHERE key='historical_referrals_processed'").fetchone():
                connection.execute("INSERT OR IGNORE INTO nxt_referral_rewards SELECT user_id, ? FROM users", (int(time.time()),))
                connection.execute("INSERT INTO nxt_meta VALUES ('historical_referrals_processed','1')")
        self.import_legacy()
        if not self.redeem_file.exists():
            atomic_write(self.redeem_file, "")

    def meta(self, key, default=None):
        with self.db() as connection:
            row = connection.execute("SELECT value FROM nxt_meta WHERE key=?", (key,)).fetchone()
        return row[0] if row else default

    def setting(self, key, value):
        with self.db() as connection:
            connection.execute("INSERT INTO nxt_meta VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (key, str(value)))

    def user(self, user_id):
        with self.db() as connection:
            row = connection.execute("SELECT * FROM users WHERE user_id=?", (user_id,)).fetchone()
        return dict(row) if row else None

    def audience(self):
        with self.db() as connection:
            ids = {row[0] for row in connection.execute("SELECT user_id FROM users")}
        with self.io_lock:
            return sorted(ids | self.known_ids)

    def register(self, user_id, username=None, referrer=None):
        created = False
        with self.db() as connection:
            if connection.execute("SELECT 1 FROM users WHERE user_id=?", (user_id,)).fetchone():
                connection.execute("UPDATE users SET username=COALESCE(?,username) WHERE user_id=?", (username, user_id))
            else:
                if referrer == user_id or not connection.execute("SELECT 1 FROM users WHERE user_id=?", (referrer,)).fetchone():
                    referrer = None
                connection.execute("INSERT INTO users (user_id,username,referrer,balance,last_bonus,access_expiry) VALUES (?,?,?,0,0,?)", (user_id, username, referrer, int(time.time()) + TRIAL_DAYS * 86400))
                created = True
        with self.io_lock:
            try:
                self.known_ids.update(self.audience())
                atomic_write(self.users_file, json.dumps(sorted(self.known_ids)))
            except OSError as error:
                log_error("users mirror", error)
        return created

    def ref_count(self, user_id):
        with self.db() as connection:
            return connection.execute("SELECT COUNT(*) FROM users WHERE referrer=?", (user_id,)).fetchone()[0]

    def reward_referral(self, user_id):
        now = int(time.time())
        with self.db() as connection:
            row = connection.execute("SELECT referrer FROM users WHERE user_id=?", (user_id,)).fetchone()
            referrer = row[0] if row else None
            if not referrer or referrer == user_id:
                return None
            owner = connection.execute("SELECT access_expiry FROM users WHERE user_id=?", (referrer,)).fetchone()
            if not owner:
                return None
            inserted = connection.execute("INSERT OR IGNORE INTO nxt_referral_rewards VALUES (?,?)", (user_id, now))
            if inserted.rowcount != 1:
                return None
            expiry = max(now, owner[0] or 0) + REFERRAL_DAYS * 86400
            connection.execute("UPDATE users SET balance=COALESCE(balance,0)+?, access_expiry=? WHERE user_id=?", (REFERRAL_BONUS, expiry, referrer))
        return referrer

    def bonus(self, user_id, amount=BONUS_AMOUNT):
        now = int(time.time())
        with self.db() as connection:
            row = connection.execute("SELECT last_bonus FROM users WHERE user_id=?", (user_id,)).fetchone()
            if not row:
                raise UserError("Use /start first.")
            remaining = COOLDOWN - (now - (row[0] or 0))
            if remaining > 0:
                return False, remaining
            connection.execute("UPDATE users SET balance=COALESCE(balance,0)+?, last_bonus=? WHERE user_id=?", (amount, now, user_id))
        return True, amount

    def import_legacy(self):
        lines = self.redeem_file.read_text(encoding="utf-8-sig").splitlines() if self.redeem_file.exists() else []
        posts = read_json(self.posts_file, {})
        if isinstance(posts, dict):
            items = posts.items()
        elif isinstance(posts, list):
            items = ((item.get("id"), item) for item in posts if isinstance(item, dict))
        else:
            items = []
            LOG.warning("Unrecognised posts.json; file left unchanged.")
        with self.db() as connection:
            for line in lines:
                parts = line.strip().split("|")
                try:
                    if len(parts) < 5:
                        continue
                    amount, limit, used, expiry = map(int, parts[1:5])
                    if min(amount, limit, used, expiry) < 0 or not parts[0]:
                        continue
                except ValueError:
                    continue
                connection.execute("""INSERT INTO nxt_redeem_codes VALUES (?,?,?,?,?)
                    ON CONFLICT(code) DO UPDATE SET used=MAX(nxt_redeem_codes.used,excluded.used)""", (parts[0].upper(), amount, limit, used, expiry))
            for key, item in items:
                if not isinstance(item, dict) or not key:
                    continue
                data = dict(item)
                content = data.get("content", data.get("text"))
                if not isinstance(content, str):
                    continue
                data["content"] = content
                data["entities"] = entity_dicts(data.get("entities"))
                owner = data.get("owner_id", data.get("user_id"))
                try:
                    owner = int(owner) if owner is not None else None
                except (ValueError, TypeError):
                    owner = None
                connection.execute("INSERT OR IGNORE INTO nxt_posts VALUES (?,?,?,?,?)", (str(data.get("id") or key), owner, data.get("chat_id"), json.dumps(data, ensure_ascii=False), int(time.time())))

    def sync_redeems(self):
        with self.io_lock:
            with self.db() as connection:
                rows = connection.execute("SELECT * FROM nxt_redeem_codes ORDER BY code").fetchall()
            replacements = {row["code"]: f"{row['code']}|{row['amount']}|{row['max_uses']}|{row['used']}|{row['expires']}" for row in rows}
            lines = self.redeem_file.read_text(encoding="utf-8-sig").splitlines() if self.redeem_file.exists() else []
            output, seen = [], set()
            for line in lines:
                key = line.split("|", 1)[0].strip().upper()
                output.append(replacements.get(key, line))
                if key in replacements:
                    seen.add(key)
            output.extend(value for key, value in replacements.items() if key not in seen)
            atomic_write(self.redeem_file, "\n".join(output) + ("\n" if output else ""))

    def mirror_redeems(self):
        try:
            self.sync_redeems()
        except OSError as error:
            log_error("redeem mirror", error)

    def create_code(self, code, amount, limit, hours):
        code = code.strip().upper()
        if not re.fullmatch(r"[A-Z0-9_-]{1,20}", code):
            raise UserError("Code: 1–20 letters, digits, underscores or hyphens.")
        if not (1 <= amount <= 10**9 and 1 <= limit <= 10**6 and 1 <= hours <= 87600):
            raise UserError("Use positive amounts, limits and hours within the supported range.")
        try:
            with self.db() as connection:
                connection.execute("INSERT INTO nxt_redeem_codes VALUES (?,?,?,0,?)", (code, amount, limit, int(time.time()) + hours * 3600))
        except sqlite3.IntegrityError:
            raise UserError("That code already exists.")
        self.mirror_redeems()
        return code

    def redeem(self, code, user_id):
        code, now = code.strip().upper(), int(time.time())
        with self.db() as connection:
            if not connection.execute("SELECT 1 FROM users WHERE user_id=?", (user_id,)).fetchone():
                raise UserError("Use /start first.")
            row = connection.execute("SELECT * FROM nxt_redeem_codes WHERE code=?", (code,)).fetchone()
            if not row:
                raise UserError("Invalid redeem code.")
            if now >= row["expires"]:
                raise UserError("Code expired.")
            if connection.execute("SELECT 1 FROM nxt_redeem_claims WHERE code=? AND user_id=?", (code, user_id)).fetchone():
                raise UserError("You have already claimed this code.")
            if row["used"] >= row["max_uses"]:
                raise UserError("Code usage limit reached.")
            connection.execute("INSERT INTO nxt_redeem_claims VALUES (?,?,?)", (code, user_id, now))
            connection.execute("UPDATE nxt_redeem_codes SET used=used+1 WHERE code=?", (code,))
            connection.execute("UPDATE users SET balance=COALESCE(balance,0)+? WHERE user_id=?", (row["amount"], user_id))
            amount = row["amount"]
        self.mirror_redeems()
        return amount

    def save_post(self, user_id, chat_id, data, post_id=None):
        data = copy.deepcopy(data)
        with self.db() as connection:
            if post_id:
                row = connection.execute("SELECT owner_id FROM nxt_posts WHERE id=?", (post_id,)).fetchone()
                if not row or (row[0] != user_id and not (row[0] is None and user_id == ADMIN_ID)):
                    raise UserError("This post cannot be edited by your account.")
                data["id"] = post_id
                connection.execute("UPDATE nxt_posts SET data_json=?,owner_id=?,chat_id=? WHERE id=?", (json.dumps(data, ensure_ascii=False), user_id, chat_id, post_id))
            else:
                for _ in range(10):
                    post_id = secrets.token_hex(3).upper()
                    data["id"] = post_id
                    try:
                        connection.execute("INSERT INTO nxt_posts VALUES (?,?,?,?,?)", (post_id, user_id, chat_id, json.dumps(data, ensure_ascii=False), int(time.time())))
                        break
                    except sqlite3.IntegrityError:
                        continue
                else:
                    raise RuntimeError("Unique post ID allocation failed.")
        return data

    def post(self, post_id, user_id):
        with self.db() as connection:
            if post_id.lower() == "latest":
                row = connection.execute("SELECT * FROM nxt_posts WHERE owner_id=? ORDER BY created_at DESC,rowid DESC LIMIT 1", (user_id,)).fetchone()
            else:
                row = connection.execute("SELECT * FROM nxt_posts WHERE id=?", (post_id,)).fetchone()
        if not row:
            raise UserError("Post not found. Create a post first.")
        if row["owner_id"] != user_id and not (row["owner_id"] is None and user_id == ADMIN_ID):
            raise UserError("This post belongs to another user.")
        return json.loads(row["data_json"])

    def state(self, chat_id, user_id):
        with self.db() as connection:
            row = connection.execute("SELECT * FROM nxt_workflows WHERE chat_id=? AND user_id=?", (chat_id, user_id)).fetchone()
        return {"stage": row["stage"], "data": json.loads(row["data_json"]), "prompt_id": row["prompt_id"]} if row else None

    def set_state(self, chat_id, user_id, stage, data=None, prompt_id=None):
        with self.db() as connection:
            connection.execute("""INSERT INTO nxt_workflows VALUES (?,?,?,?,?) ON CONFLICT(chat_id,user_id)
                DO UPDATE SET stage=excluded.stage,data_json=excluded.data_json,prompt_id=excluded.prompt_id""", (chat_id, user_id, stage, json.dumps(data or {}, ensure_ascii=False), prompt_id))

    def clear_state(self, chat_id, user_id):
        with self.db() as connection:
            connection.execute("DELETE FROM nxt_workflows WHERE chat_id=? AND user_id=?", (chat_id, user_id))

    def channels(self):
        entries = json.loads(self.meta("force_join_channels", "[]"))
        if not isinstance(entries, list):
            raise UserError("Owner needs to repair Force Join settings.")
        return entries

    def change_channels(self, action, entry=None, channel_id=None):
        with self.db() as connection:
            row = connection.execute("SELECT value FROM nxt_meta WHERE key='force_join_channels'").fetchone()
            entries = [] if action == "clear" else json.loads(row[0]) if row else []
            if action == "add":
                entries = [item for item in entries if int(item["id"]) != int(entry["id"])]
                if len(entries) >= 40:
                    raise UserError("Remove a channel before adding another.")
                entries.append(entry)
            elif action == "remove":
                entries = [item for item in entries if int(item["id"]) != int(channel_id)]
            elif action != "clear":
                raise ValueError("Unknown channel operation.")
            connection.execute("INSERT INTO nxt_meta VALUES ('force_join_channels',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (json.dumps(entries, ensure_ascii=False),))


class EmojiCatalog:
    def __init__(self):
        self.lock = threading.RLock()
        self.records, self.unavailable = {}, set()
        self.mapping = {key: list(values) for key, values in BUNDLE["map"].items()}
        self.flags = dict(BUNDLE["flags"])
        self.pool = list(BUNDLE["pool"])
        self.reverse = {str(value): key for key, values in self.mapping.items() for value in values}
        self.reverse.update({str(value): key for key, value in self.flags.items()})
        self.ui = {glyph: str(value) for glyph, value in BUNDLE["ui"].values() if value}
        self.reverse.update({str(value): glyph for glyph, value in BUNDLE["ui"].values() if value})

    def candidates(self):
        values = list(self.ui.values())
        values += [value for options in self.mapping.values() for value in options]
        values += list(self.flags.values()) + self.pool + list(BUNDLE["extra_ids"])
        return list(dict.fromkeys(map(str, values)))

    def accept(self, stickers, requested):
        found = set()
        with self.lock:
            for sticker in stickers:
                custom_id = str(getattr(sticker, "custom_emoji_id", "") or "")
                if not custom_id:
                    continue
                found.add(custom_id)
                glyph = getattr(sticker, "emoji", None) or self.reverse.get(custom_id, "✨")
                record = {"id": custom_id, "emoji": glyph, "file_id": sticker.file_id,
                          "animated": bool(getattr(sticker, "is_animated", False) or getattr(sticker, "is_video", False))}
                self.records[custom_id] = record
                self.reverse[custom_id] = glyph
                values = self.mapping.setdefault(glyph, [])
                if custom_id not in values:
                    values.append(custom_id)
            self.unavailable.update(set(map(str, requested)) - found)
            self.unavailable.difference_update(found)

    def choose(self, glyph="✨", ui=False):
        with self.lock:
            key = glyph if glyph in self.mapping or glyph in self.flags else glyph.replace("\ufe0f", "").replace("\ufe0e", "").replace("\u200d", "")
            values = list(self.mapping.get(key, []))
            if key in self.flags:
                values = [self.flags[key]] + values
            if ui and glyph in self.ui:
                values = [self.ui[glyph]] + values
            values = [str(value) for value in dict.fromkeys(values) if str(value) not in self.unavailable]
            if ui:
                animated = [value for value in values if self.records.get(value, {}).get("animated")]
                if animated:
                    return animated[0]
            if values:
                return values[0]
            pool = [value for value in self.pool if value not in self.unavailable]
            if not pool:
                return None
            return pool[int(hashlib.md5(glyph.encode()).hexdigest(), 16) % len(pool)]

    def alt(self, custom_id):
        with self.lock:
            return self.reverse.get(str(custom_id), "✨")

    def validate_chunk(self, values):
        try:
            stickers = tg(BOT.get_custom_emoji_stickers, values, max_wait=30)
            self.accept(stickers, values)
            return True
        except Exception as error:
            log_error("emoji validation", error)
            return False

    def initialize(self):
        cached = STORE.meta("emoji_catalog", "")
        if cached:
            try:
                payload = json.loads(cached)
                if payload.get("bot_id") == BOT_ME.id:
                    for record in payload.get("records", []):
                        self.records[record["id"]] = record
                        self.reverse[record["id"]] = record["emoji"]
                        self.mapping.setdefault(record["emoji"], []).append(record["id"])
            except (ValueError, KeyError, TypeError) as error:
                log_error("emoji cache", error)
        # Validate the basic UI IDs before polling, then load the large pool
        # outside handler threads so /start stays responsive.
        self.validate_chunk(list(dict.fromkeys(self.ui.values())))

        def background():
            values = self.candidates()
            for index in range(0, len(values), 200):
                if STOP.is_set():
                    break
                self.validate_chunk(values[index:index + 200])
            with self.lock:
                payload = {"bot_id": BOT_ME.id, "records": list(self.records.values())}
            STORE.setting("emoji_catalog", json.dumps(payload, ensure_ascii=False))
            LOG.info("Custom emoji validation complete: %s confirmed.", len(self.records))

        threading.Thread(target=background, name="emoji-validation", daemon=True).start()


def premium_text(text, original_entities=(), ui=False, styled=True):
    original = entity_dicts(original_entities)
    valid_entities(text, original)
    if styled:
        text = smallcaps(text, original)
    entities = list(original)
    protected = protected_ranges(text, original)
    protected += [(item["offset"], item["offset"] + item["length"]) for item in original if item["type"] in {"text_link", "text_mention", "date_time"}]
    budget = max(0, 94 - len(entities))
    for match in emoji.emoji_list(text):
        if budget <= 0:
            break
        start, length = u16(text[:match["match_start"]]), u16(match["emoji"])
        if any(start < end and start + length > begin for begin, end in protected):
            continue
        custom_id = CATALOG.choose(match["emoji"], ui=ui)
        if custom_id:
            entities.append({"type": "custom_emoji", "offset": start, "length": length, "custom_emoji_id": str(custom_id)})
            budget -= 1
    if text and not any(item["type"] in {"bold", "code", "pre"} for item in entities):
        entities.append({"type": "bold", "offset": 0, "length": u16(text)})
    return text, sorted(entities, key=lambda item: (item["offset"], -item["length"]))


def wait_cancel(seconds, cancel=None):
    deadline = time.monotonic() + seconds
    while time.monotonic() < deadline:
        if STOP.is_set() or cancel is not None and cancel.is_set():
            raise UserError("Operation cancelled.")
        STOP.wait(min(0.5, max(0, deadline - time.monotonic())))


def soften_markup(markup, remove_icons=True, remove_styles=False):
    changed = False
    rows = getattr(markup, "inline_keyboard", None)
    if rows is None:
        rows = getattr(markup, "keyboard", [])
    for row in rows or []:
        for item in row:
            if isinstance(item, str):
                continue
            get = item.get if isinstance(item, dict) else lambda key, default=None: getattr(item, key, default)
            def put(key, value):
                if isinstance(item, dict):
                    if value is None:
                        item.pop(key, None)
                    else:
                        item[key] = value
                else:
                    setattr(item, key, value)
            if remove_icons and get("icon_custom_emoji_id"):
                fallback = CATALOG.alt(get("icon_custom_emoji_id"))
                put("text", f"{fallback} {get('text')}")
                put("icon_custom_emoji_id", None)
                changed = True
            if remove_styles and get("style"):
                put("style", None)
                changed = True
    return changed


def tg(function, *args, max_wait=5, cancel=None, effect_fallback=True, **kwargs):
    options, rate_tries = dict(kwargs), 0
    for _ in range(8):
        try:
            return function(*args, **options)
        except ApiTelegramException as error:
            payload = getattr(error, "result_json", {}) or {}
            code = payload.get("error_code", getattr(error, "error_code", 0))
            description = str(payload.get("description", error)).lower()
            if code == 429:
                delay = int(payload.get("parameters", {}).get("retry_after", 1))
                if delay > max_wait or rate_tries >= 3:
                    raise UserError(f"Telegram limit. Try again in {delay} seconds.")
                rate_tries += 1
                wait_cancel(delay + 0.1, cancel)
                continue
            if code == 400:
                if "message is not modified" in description:
                    return None
                if effect_fallback and options.get("message_effect_id") and "effect" in description:
                    options.pop("message_effect_id", None)
                    continue
                if any(word in description for word in ("custom_emoji", "custom emoji", "emoji_id", "icon_custom", "button_icon", "button_style", "button style")):
                    changed = False
                    for key in ("entities", "caption_entities"):
                        if options.get(key):
                            before = options[key]
                            after = [item for item in before if (item.get("type") if isinstance(item, dict) else item.type) != "custom_emoji"]
                            if len(before) != len(after):
                                options[key], changed = after, True
                    if options.get("reply_markup"):
                        changed = soften_markup(options["reply_markup"], remove_styles="style" in description) or changed
                    if changed:
                        continue
            raise
    raise UserError("Telegram repeatedly rejected this request.")


def setting_on(key, default="1"):
    return STORE.meta(key, default) == "1"


def effect_id():
    saved = STORE.meta("message_effect_id", None)
    return DEFAULT_EFFECT_ID if saved is None else saved


def effect_args(chat_id):
    value = effect_id()
    return {"message_effect_id": str(value)} if value and isinstance(chat_id, int) and chat_id > 0 else {}


def button(label, action=None, url=None, color="blue", glyph="✨", reply=False):
    found = emoji.emoji_list(label)
    if found and glyph == "✨":
        glyph = found[0]["emoji"]
    plain = emoji.replace_emoji(label, replace="").strip() or "Open"
    if color == "yellow":
        glyph = "💛"
    text = plain.translate(SMALL_TABLE)
    custom_id = CATALOG.choose(glyph, ui=True)
    options = {"text": text}
    style = {"blue": "primary", "red": "danger", "green": "success"}.get(color)
    if style:
        options["style"] = style
    if custom_id:
        options["icon_custom_emoji_id"] = str(custom_id)
    else:
        options["text"] = f"{glyph} {text}"
    if reply:
        return types.KeyboardButton(**options)
    if action is not None:
        if not 1 <= len(action.encode()) <= 64:
            raise ValueError("Callback payload exceeds Telegram limit.")
        options["callback_data"] = action
    elif url is not None:
        options["url"] = good_url(url)
    else:
        raise ValueError("Button has no action.")
    return types.InlineKeyboardButton(**options)


def main_menu(user_id):
    keyboard = types.ReplyKeyboardMarkup(resize_keyboard=True, row_width=2)
