def cancel_keys(back=None):
    keyboard = types.InlineKeyboardMarkup()
    if back:
        keyboard.add(button("Back", action=back, glyph="⬅️"))
    keyboard.add(button("Cancel", action="cancel", color="red", glyph="❌"))
    return keyboard


def ui(chat_id, text, markup=None, codes=(), links=(), animated=True):
    # One animated custom emoji is attached to every nonempty UI line.
    lines = []
    for line in str(text).splitlines():
        if line.strip() and not any(match["match_start"] == 0 for match in emoji.emoji_list(line.lstrip())):
            line = "✨ " + line
        lines.append(line)
    text = "\n".join(lines)
    entities = []
    for value in dict.fromkeys(map(str, codes)):
        if not value:
            continue
        position = 0
        while (index := text.find(value, position)) >= 0:
            entities.append({"type": "code", "offset": u16(text[:index]), "length": u16(value)})
            position = index + len(value)
    for label, destination in dict.fromkeys(links):
        if not label:
            continue
        position = 0
        while (index := text.find(label, position)) >= 0:
            entities.append({"type": "text_link", "offset": u16(text[:index]), "length": u16(label), "url": destination})
            position = index + len(label)
    text, entities = premium_text(text, entities, ui=True)
    if text and setting_on("quote_theme") and not any(item["type"] in {"code", "pre", "blockquote", "expandable_blockquote"} for item in entities):
        entities.append({"type": "blockquote", "offset": 0, "length": u16(text)})
    if u16(text) > 4096:
        raise UserError("This response is too long to display.")
    return tg(BOT.send_message, chat_id, text, entities=entity_objects(entities), reply_markup=markup, **(effect_args(chat_id) if animated else {}))


def ask(chat_id, user_id, stage, text, data=None, back=None, codes=()):
    message = ui(chat_id, text, cancel_keys(back), codes=codes)
    STORE.set_state(chat_id, user_id, stage, data, message.message_id)


def ack(call, text=None):
    try:
        tg(BOT.answer_callback_query, call.id, text=smallcaps(text or ""), max_wait=0)
    except Exception as error:
        log_error("callback answer", error)


def owner_only(chat_id, user_id):
    if user_id != ADMIN_ID:
        raise UserError("Owner only.")
    if chat_id != ADMIN_ID:
        raise UserError("Use Owner Panel in the private chat.")


def owner_url():
    return f"tg://user?id={ADMIN_ID}"


def owner_name():
    global OWNER_NAME
    if time.monotonic() < OWNER_NAME[1]:
        return OWNER_NAME[0]
    name = "Owner"
    try:
        profile = tg(BOT.get_chat, ADMIN_ID, max_wait=0)
        name = " ".join(part for part in [getattr(profile, "first_name", ""), getattr(profile, "last_name", "")] if part) or name
    except Exception as error:
        log_error("owner profile", error)
    OWNER_NAME = name, time.monotonic() + 60
    return name


def ref_link(user_id):
    return f"https://t.me/{BOT_ME.username}?start={user_id}"


def share_link(user_id):
    return "https://t.me/share/url?" + urlencode({"url": ref_link(user_id), "text": "Join KD Premium Emoji Bot"})


def has_access(user_id):
    user = STORE.user(user_id) or {}
    return (user.get("access_expiry") or 0) > int(time.time())


def days_left(user_id):
    user = STORE.user(user_id) or {}
    return max(0, ((user.get("access_expiry") or 0) - int(time.time())) // 86400)


def missing_channels(user_id):
    missing = []
    for entry in STORE.channels():
        try:
            member = tg(BOT.get_chat_member, int(entry["id"]), user_id)
            joined = member.status not in {"left", "kicked"}
            if member.status == "restricted":
                joined = bool(getattr(member, "is_member", False))
            if not joined:
                missing.append(entry)
        except Exception as error:
            log_error("membership", error)
            missing.append(entry)
    return missing


def join_prompt(chat_id, missing):
    keyboard = types.InlineKeyboardMarkup()
    for entry in missing:
        keyboard.add(button("Join " + str(entry.get("title") or "Channel")[:36], url=entry["url"], glyph="📢"))
    keyboard.add(button("VERIFIED JOIN", action="check_join", color="green", glyph="✅"))
    total = len(STORE.channels())
    ui(chat_id, f"⭐ Welcome to KD Premium Emoji Bot\n\n❌ Access denied\nJoined: {total-len(missing)}/{total}\nJoin the remaining channels and tap Verified Join.", keyboard)


def require_join(chat_id, user_id):
    if not STORE.user(user_id):
        ui(chat_id, "Use /start first.")
        return False
    missing = missing_channels(user_id)
    if missing:
        join_prompt(chat_id, missing)
        return False
    rewarded = STORE.reward_referral(user_id)
    if rewarded:
        try:
            ui(rewarded, f"🎉 New verified referral\nUser ID: {user_id}\n+{REFERRAL_BONUS} points\n+{REFERRAL_DAYS} access day\nDays left: {days_left(rewarded)}")
        except Exception as error:
            log_error("referral notification", error)
    return True


