def invalidate_intro(chat_id, user_id):
    with INTRO_LOCK:
        key = chat_id, user_id
        INTRO_TOKENS[key] = INTRO_TOKENS.get(key, 0) + 1
        return INTRO_TOKENS[key]


def start_animation(message):
    chat_id, user_id = message.chat.id, message.from_user.id
    generation = invalidate_intro(chat_id, user_id)

    def run():
        popup = None
        custom_id = STORE.meta("start_custom_emoji_id") or CATALOG.choose("✨", ui=True)
        try:
            if setting_on("start_reaction"):
                try:
                    if not custom_id:
                        raise UserError("No custom reaction available.")
                    tg(BOT.set_message_reaction, chat_id, message.message_id,
                       reaction=[types.ReactionTypeCustomEmoji(str(custom_id))], is_big=True, max_wait=0)
                except Exception:
                    # Telegram permits custom reactions only when allowed.
                    with contextlib.suppress(Exception):
                        tg(BOT.set_message_reaction, chat_id, message.message_id,
                           reaction=[types.ReactionTypeEmoji("👍")], is_big=True, max_wait=0)
            with INTRO_LOCK:
                if INTRO_TOKENS.get((chat_id, user_id)) != generation:
                    return
            if setting_on("start_popup"):
                glyph = CATALOG.alt(custom_id) if custom_id else "✨"
                entities = [types.MessageEntity(type="custom_emoji", offset=0, length=u16(glyph), custom_emoji_id=str(custom_id))] if custom_id else []
                popup = tg(BOT.send_message, chat_id, glyph, entities=entities, **effect_args(chat_id))
                STOP.wait(1.2)
        except Exception as error:
            log_error("start animation", error)
        finally:
            if popup is not None:
                with contextlib.suppress(Exception):
                    tg(BOT.delete_message, chat_id, popup.message_id)
        if STOP.is_set():
            return
        with user_lock(chat_id, user_id):
            with INTRO_LOCK:
                if INTRO_TOKENS.get((chat_id, user_id)) != generation:
                    return
            try:
                if require_join(chat_id, user_id):
                    welcome(chat_id, user_id)
            except Exception as error:
                log_error("welcome", error)

    if INTRO_POOL is None:
        run()
    else:
        INTRO_POOL.submit(run)


