def welcome_video_config():
    raw = STORE.meta("welcome_video", "")
    if not raw:
        return None
    try:
        config = json.loads(raw)
        if not isinstance(config, dict) or not isinstance(config.get("file_id"), str) or not config["file_id"].strip():
            raise ValueError("Invalid welcome video configuration.")
        if not isinstance(config.get("spoiler", False), bool):
            raise ValueError("Invalid welcome video mode.")
        return config
    except (ValueError, TypeError) as error:
        log_error("welcome video configuration", error)
        return None


def send_welcome_video(chat_id, required=False):
    config = welcome_video_config()
    if not config:
        if required:
            raise UserError("Set a welcome video first.")
        return False
    try:
        tg(BOT.send_video, chat_id, config["file_id"], has_spoiler=config.get("spoiler", False),
           supports_streaming=True, **effect_args(chat_id))
        return True
    except Exception as error:
        log_error("welcome video", error)
        if required:
            raise UserError("Welcome video could not be sent. Upload it again or try later.") from None
        return False


