def add_channel(message):
    owner_only(message.chat.id, message.from_user.id)
    chat = forwarded_chat(message)
    target = chat.id if chat else None
    if target is None and re.fullmatch(r"-?\d+", (message.text or "").strip()):
        target = int(message.text.strip())
    if target is None:
        raise UserError("Forward a channel post or send its numeric chat ID.")
    chat = tg(BOT.get_chat, target)
    if chat.type not in {"channel", "supergroup", "group"}:
        raise UserError("Choose a channel or group.")
    owner_member = tg(BOT.get_chat_member, chat.id, ADMIN_ID)
    bot_member = tg(BOT.get_chat_member, chat.id, BOT_ME.id)
    if owner_member.status not in {"administrator", "creator"}:
        raise UserError("You must be an administrator there.")
    if bot_member.status not in {"administrator", "creator"}:
        raise UserError("Make this bot an administrator there first.")
    username = getattr(chat, "username", None)
    destination = f"https://t.me/{username}" if username else getattr(chat, "invite_link", None)
    if not destination:
        if not getattr(bot_member, "can_invite_users", False):
            raise UserError("Give the bot permission to invite users.")
        destination = tg(BOT.create_chat_invite_link, chat.id, name="KD bot access", creates_join_request=False).invite_link
    STORE.change_channels("add", entry={"id": chat.id, "title": chat.title or "Channel", "url": good_url(destination)})
    join_panel(message.chat.id)


def set_effect(message, argument=""):
    owner_only(message.chat.id, message.from_user.id)
    value = argument.strip()
    if value.lower() == "off":
        STORE.setting("message_effect_id", "")
        ui(message.chat.id, "Effects disabled.")
        return
    if not value:
        replied = getattr(message, "reply_to_message", None)
        value = str(getattr(replied, "effect_id", "") or "")
    if not value:
        ui(message.chat.id, "Reply /effect to a message with a native Telegram effect, or use Effects & Theme.")
        return
    if not re.fullmatch(r"\d{1,20}", value):
        raise UserError("Invalid message-effect identifier.")
    preview = tg(BOT.send_message, message.chat.id, smallcaps("✨ Effect preview"), message_effect_id=value, effect_fallback=False)
    if str(getattr(preview, "effect_id", "") or "") != value:
        raise UserError("Telegram did not confirm this effect; previous setting kept.")
    STORE.setting("message_effect_id", value)
    ui(message.chat.id, "Effect saved.")


def validate_post(data):
    text = data.get("content", data.get("text", "")) or ""
    media = bool(data.get("photo_id") or data.get("video_id"))
    limit = 1024 if media else 4096
    if u16(text) > limit:
        raise UserError(f"Post exceeds the {limit}-unit text or caption budget.")
    if not text and not media:
        raise UserError("Post is empty.")
    valid_entities(text, data.get("entities") or [])


