def save_post_content(message, previous=None):
    if getattr(message, "media_group_id", None):
        raise UserError("Send one photo or video at a time; albums are not supported.")
    data = dict(previous or {})
    if message.content_type == "text":
        data.update(text=message.text or "", entities=entity_dicts(message.entities))
    elif message.content_type in {"photo", "video"}:
        data.update(text=message.caption or "", entities=entity_dicts(message.caption_entities),
                    photo_id=message.photo[-1].file_id if message.content_type == "photo" else None,
                    video_id=message.video.file_id if message.content_type == "video" else None)
    else:
        raise UserError("Send text, one photo or one video.")
    # Old converted content must not shadow newly edited raw text.
    data.pop("content", None)
    validate_post(data)
    if data.get("photo_id") or data.get("video_id"):
        button_choice(message.chat.id, message.from_user.id, data)
    else:
        media_choice(message.chat.id, message.from_user.id, data)


def save_photo(message, data):
    if not getattr(message, "photo", None) or getattr(message, "media_group_id", None):
        raise UserError("Send a single photo or use /cancel.")
    data = dict(data, photo_id=message.photo[-1].file_id, video_id=None)
    validate_post(data)
    button_choice(message.chat.id, message.from_user.id, data)


def save_video(message, data):
    if not getattr(message, "video", None) or getattr(message, "media_group_id", None):
        raise UserError("Send a single video or use /cancel.")
    data = dict(data, video_id=message.video.file_id, photo_id=None)
    validate_post(data)
    button_choice(message.chat.id, message.from_user.id, data)


def send_post(chat_id, data):
    outgoing = copy.deepcopy(data)
    validate_post(outgoing)
    text = outgoing.get("content", outgoing.get("text", "")) or ""
    entities = entity_dicts(outgoing.get("entities"))
    if text and setting_on("quote_theme") and not any(item["type"] in {"blockquote", "expandable_blockquote", "pre", "code"} for item in entities):
        entities.append({"type": "blockquote", "offset": 0, "length": u16(text)})
    keyboard = None
    if outgoing.get("btn_name") and outgoing.get("btn_url"):
        keyboard = types.InlineKeyboardMarkup()
        keyboard.add(button(outgoing["btn_name"], url=outgoing["btn_url"], glyph="🔗"))
    options = dict(reply_markup=keyboard, **effect_args(chat_id))
    if outgoing.get("photo_id"):
        return tg(BOT.send_photo, chat_id, outgoing["photo_id"], caption=text, caption_entities=entity_objects(entities), **options)
    if outgoing.get("video_id"):
        return tg(BOT.send_video, chat_id, outgoing["video_id"], caption=text, caption_entities=entity_objects(entities), **options)
    return tg(BOT.send_message, chat_id, text, entities=entity_objects(entities), **options)


