def finish_post(chat_id, user_id, data):
    validate_post(data)
    raw_text, raw_entities = data.get("text", ""), entity_dicts(data.get("entities"))
    text, entities = premium_text(raw_text, raw_entities)
    saved = dict(data, raw_text=raw_text, raw_entities=raw_entities, content=text, entities=entities)
    validate_post(saved)
    saved = STORE.save_post(user_id, chat_id, saved, data.get("edit_id"))
    STORE.clear_state(chat_id, user_id)
    try:
        send_post(chat_id, saved)
    except Exception:
        ui(chat_id, "Post saved. Preview delivery was not confirmed; use /send latest with the destination ID.")
        raise
    post_controls(chat_id, saved)


def destination_id(message):
    chat = forwarded_chat(message)
    if chat:
        return chat.id
    value = (message.text or "").strip()
    if re.fullmatch(r"-?\d+", value):
        return int(value)
    if re.fullmatch(r"@[A-Za-z0-9_]+", value):
        return value
    raise UserError("Forward a channel post or send its numeric chat ID.")


def publish(chat_id, user_id, post_id, target):
    if not require_post(chat_id, user_id):
        return False
    data = STORE.post(post_id, user_id)
    target = int(target) if str(target).lstrip("-").isdigit() else target
    chat = tg(BOT.get_chat, target)
    if chat.type not in {"channel", "supergroup", "group"}:
        raise UserError("Choose a channel or group.")
    user_member = tg(BOT.get_chat_member, chat.id, user_id)
    bot_member = tg(BOT.get_chat_member, chat.id, BOT_ME.id)
    if user_member.status not in {"administrator", "creator"}:
        raise UserError("You must be an administrator of the destination.")
    if bot_member.status not in {"administrator", "creator"}:
        raise UserError("Make this bot an administrator of the destination.")
    if chat.type == "channel" and bot_member.status != "creator" and not getattr(bot_member, "can_post_messages", False):
        raise UserError("Give the bot permission to post messages.")
    send_post(chat.id, data)
    ui(chat_id, "✅ Sent successfully.")
    return True


def cancel(chat_id, user_id):
    invalidate_intro(chat_id, user_id)
    STORE.clear_state(chat_id, user_id)
    if user_id == ADMIN_ID and BROADCAST_LOCK.locked():
        BROADCAST_CANCEL.set()
    ui(chat_id, "✅ Cancelled.", main_menu(user_id))


def broadcast(message):
    owner_only(message.chat.id, message.from_user.id)
    if not BROADCAST_LOCK.acquire(blocking=False):
        raise UserError("A broadcast is already running. Use /cancel to stop it.")
    BROADCAST_CANCEL.clear()
    STORE.clear_state(message.chat.id, message.from_user.id)
    source_chat, source_message = message.chat.id, message.message_id
    recipients = STORE.audience()

    def worker():
        success = failed = 0
        try:
            for user_id in recipients:
                if STOP.is_set() or BROADCAST_CANCEL.is_set():
                    break
                try:
                    tg(BOT.copy_message, user_id, source_chat, source_message,
                       max_wait=3600, cancel=BROADCAST_CANCEL, **effect_args(user_id))
                    success += 1
                except Exception as error:
                    if STOP.is_set() or BROADCAST_CANCEL.is_set():
                        break
                    failed += 1
                    log_error("broadcast delivery", error)
                wait_cancel(0.06, BROADCAST_CANCEL)
        except UserError:
            pass
        except Exception as error:
            log_error("broadcast worker", error)
        finally:
            BROADCAST_LOCK.release()
            if not STOP.is_set():
                with contextlib.suppress(Exception):
                    status = "Cancelled" if BROADCAST_CANCEL.is_set() else "Complete"
                    ui(source_chat, f"📢 Broadcast {status}\nSuccess: {success}\nFailed: {failed}\nAudience: {len(recipients)}")
    threading.Thread(target=worker, name="broadcast", daemon=True).start()
    ui(source_chat, "📢 Broadcast started. Use /cancel to stop it.")


def command(message):
    chat_id, user_id = message.chat.id, message.from_user.id
    name, _, argument = (message.text or "").partition(" ")
    name, argument = name.split("@", 1)[0].lower(), argument.strip()
    if name == "/start":
        referrer = None
        with contextlib.suppress(ValueError, IndexError):
            referrer = int(argument.split()[0])
        STORE.clear_state(chat_id, user_id)
        STORE.register(user_id, message.from_user.username, referrer)
        start_animation(message)
    elif name == "/cancel":
        cancel(chat_id, user_id)
    elif name == "/access":
        access_status(chat_id, user_id)
    elif name == "/effect":
        set_effect(message, argument)
    elif name == "/send":
        parts = argument.split()
        if len(parts) != 2:
            raise UserError("Use /send latest -100CHAT_ID or use the Send to Channel button.")
        publish(chat_id, user_id, parts[0], parts[1])
    elif name == "/help":
        ui(chat_id, "⭐ KD Premium Emoji Bot\n/start — Open the menu\n/access — Check access\n/cancel — Cancel the current step\n/send — Publish a saved post\n\nUse Make Post to create a text, photo or video post.\nOwner settings are available in Owner Panel.", main_menu(user_id))
    else:
        raise UserError("Unknown command. Use /help or /cancel.")


def menu_action(message, action):
    chat_id, user_id = message.chat.id, message.from_user.id
    STORE.clear_state(chat_id, user_id)
    if action == "contact":
        keyboard = types.InlineKeyboardMarkup()
        keyboard.add(button("Contact Owner", url=owner_url(), color="red", glyph="👑"))
        ui(chat_id, "Tap to contact the owner.", keyboard)
        return
    if action == "owner":
        owner_panel(chat_id, user_id)
        return
    if action == "create_redeem":
        owner_only(chat_id, user_id)
        ask(chat_id, user_id, "create_redeem", "Send CODE AMOUNT LIMIT HOURS\nExample: FREE100 100 20 24", codes=["FREE100 100 20 24"])
        return
    if not require_join(chat_id, user_id):
        return
    if action == "post":
        if require_post(chat_id, user_id):
            ask(chat_id, user_id, "post_text", "🎀 Send your post with normal emoji.")
    elif action == "balance":
        user = STORE.user(user_id)
        keyboard = types.InlineKeyboardMarkup()
        keyboard.add(button("Developer", url=owner_url(), glyph="🛠"))
        ui(chat_id, f"👤 Name: {message.from_user.first_name}\nBalance: {user['balance'] or 0} points\nDate: {datetime.now(IST):%Y-%m-%d}", keyboard)
    elif action == "refer":
        referrals(chat_id, user_id)
    elif action == "bonus":
        keyboard = types.InlineKeyboardMarkup()
        keyboard.add(button("CLAIM BONUS", action="claim_bonus", color="green", glyph="🎁"))
        ui(chat_id, "🎉 Claim your bonus\nAvailable once every 24 hours.", keyboard)
    elif action == "redeem":
        ask(chat_id, user_id, "redeem", "🎁 Send your redeem code.")


MENU_ACTIONS = {normal_label(value): key for key, value in MENU.items()}
MENU_ACTIONS.update({"refer": "refer", "admin panel": "owner", "create redeem": "create_redeem"})


def process_input(message, state):
    chat_id, user_id = message.chat.id, message.from_user.id
    stage, data = state["stage"], state["data"]
    owner_stages = {"create_redeem", "broadcast", "force_channel", "effect_message", "start_emoji", "welcome_video"}
    if stage in owner_stages:
        owner_only(chat_id, user_id)
    elif not require_join(chat_id, user_id):
        return
    if stage in {"post_text", "photo", "video", "button_name", "button_url", "post_destination"} and not require_post(chat_id, user_id):
        return
    if stage == "post_text":
        save_post_content(message, data)
    elif stage == "photo":
        save_photo(message, data)
    elif stage == "video":
        save_video(message, data)
    elif stage == "button_name":
        name = (message.text or "").strip()
        if not 1 <= len(name) <= 64:
            raise UserError("Send a button name containing 1–64 characters.")
        ask(chat_id, user_id, "button_url", "Send the button URL.", dict(data, btn_name=name), back="back_buttons")
    elif stage == "button_url":
        finish_post(chat_id, user_id, dict(data, btn_url=good_url(message.text or "")))
    elif stage == "redeem":
        if not message.text:
            raise UserError("Send the code as text.")
        amount = STORE.redeem(message.text, user_id)
        STORE.clear_state(chat_id, user_id)
        ui(chat_id, f"🎉 Redeem claimed\nAmount added: {amount} points\nNew balance: {STORE.user(user_id)['balance']} points")
    elif stage == "create_redeem":
        parts = (message.text or "").split()
        if len(parts) != 4:
            raise UserError("Use CODE AMOUNT LIMIT HOURS. Example: FREE100 100 20 24")
        try:
            amount, limit, hours = map(int, parts[1:])
        except ValueError:
            raise UserError("Amount, limit and hours must be integers.")
        code = STORE.create_code(parts[0], amount, limit, hours)
        STORE.clear_state(chat_id, user_id)
        ui(chat_id, f"✅ Redeem code created\nCode: {code}\nAmount: {amount} points\nLimit: {limit} users\nExpiry: {hours} hours", codes=[code])
    elif stage == "broadcast":
        broadcast(message)
    elif stage == "welcome_video":
        save_welcome_video(message, data)
    elif stage == "force_channel":
        add_channel(message)
    elif stage == "effect_message":
        value = getattr(message, "effect_id", None) or (getattr(message, "json", {}) or {}).get("effect_id")
        if not value:
            raise UserError("Send a message with a native Telegram message effect.")
        set_effect(message, str(value))
        theme_panel(chat_id)
    elif stage == "start_emoji":
        custom = next((item for item in entity_dicts(message.entities or message.caption_entities) if item["type"] == "custom_emoji"), None)
        if not custom:
            raise UserError("Send one premium custom emoji in a text message.")
        values = [custom["custom_emoji_id"]]
        stickers = tg(BOT.get_custom_emoji_stickers, values)
        if not stickers:
            raise UserError("That custom emoji is unavailable.")
        CATALOG.accept(stickers, values)
        STORE.setting("start_custom_emoji_id", values[0])
        theme_panel(chat_id)
    elif stage == "post_destination":
        if publish(chat_id, user_id, data["id"], destination_id(message)):
            STORE.clear_state(chat_id, user_id)
    elif stage in {"media_choice", "button_choice"}:
        raise UserError("Use the buttons on the latest prompt or /cancel.")
    else:
        raise UserError("Use /cancel, then start the workflow again.")


def on_message(message):
    if not message.from_user or message.from_user.is_bot:
        return
    chat_id, user_id = message.chat.id, message.from_user.id
    with user_lock(chat_id, user_id):
        try:
            text = message.text or ""
            if not text.startswith("/start"):
                invalidate_intro(chat_id, user_id)
            if text.startswith("/"):
                command(message)
            elif normal_label(text) in MENU_ACTIONS:
                menu_action(message, MENU_ACTIONS[normal_label(text)])
            elif (state := STORE.state(chat_id, user_id)) is not None:
                process_input(message, state)
            else:
                ui(chat_id, "Use /start to open the menu.")
        except UserError as error:
            with contextlib.suppress(Exception):
                ui(chat_id, f"❌ {error}")
        except Exception as error:
            log_error("message handler", error)
            with contextlib.suppress(Exception):
                ui(chat_id, "❌ Operation could not be confirmed. Try again or use /cancel.")


def active_prompt(call, stages):
    state = STORE.state(call.message.chat.id, call.from_user.id)
    if not state or state["stage"] not in stages or state["prompt_id"] != call.message.message_id:
        raise UserError("This prompt is no longer active. Use the latest prompt or /cancel.")
    return state["data"]


def callback_action(call):
    chat_id, user_id, action = call.message.chat.id, call.from_user.id, call.data or ""
    if action.startswith("admin_"):
        owner_only(chat_id, user_id)
    if action == "cancel":
        cancel(chat_id, user_id)
    elif action in {"home", "check_join"}:
        if action == "home":
            STORE.clear_state(chat_id, user_id)
        if require_join(chat_id, user_id):
            welcome(chat_id, user_id)
    elif action == "admin_owner_panel":
        owner_panel(chat_id, user_id)
    elif action == "admin_status":
        ui(chat_id, f"📊 Bot status\nTotal users: {len(STORE.audience())}\nBroadcast running: {BROADCAST_LOCK.locked()}\nValidated custom emoji: {len(CATALOG.records)}")
    elif action == "admin_broadcast":
        if BROADCAST_LOCK.locked():
            raise UserError("A broadcast is running. Use /cancel.")
        ask(chat_id, user_id, "broadcast", "📢 Send the broadcast message. Use /cancel to cancel.")
    elif action == "admin_create_redeem":
        ask(chat_id, user_id, "create_redeem", "Send CODE AMOUNT LIMIT HOURS\nExample: FREE100 100 20 24", codes=["FREE100 100 20 24"])
    elif action == "admin_force_join":
        join_panel(chat_id)
    elif action == "admin_join_add":
        ask(chat_id, user_id, "force_channel", "Make the bot an administrator first.\nForward a channel post or send its numeric ID.", back="admin_force_join")
    elif action.startswith("admin_join_remove_"):
        try:
            target = int(action[len("admin_join_remove_"):])
        except ValueError:
            raise UserError("Invalid channel selection.")
        STORE.change_channels("remove", channel_id=target)
        join_panel(chat_id)
    elif action == "admin_join_clear":
        STORE.change_channels("clear")
        join_panel(chat_id)
    elif action == "admin_theme":
        theme_panel(chat_id)
    elif action == "admin_welcome_video":
        welcome_video_panel(chat_id, user_id)
    elif action in {"admin_welcome_normal", "admin_welcome_spoiler"}:
        hidden = action == "admin_welcome_spoiler"
        mode = "hidden / spoiler" if hidden else "normal"
        ask(chat_id, user_id, "welcome_video", f"🎥 Send one {mode} welcome video.\nSend it as a video, not a document or album.\nUse Back or /cancel to keep the saved video.", {"spoiler": hidden}, back="admin_welcome_video")
    elif action == "admin_welcome_preview":
        send_welcome_video(chat_id, required=True)
        welcome_video_panel(chat_id, user_id)
    elif action == "admin_welcome_remove":
        STORE.setting("welcome_video", "")
        welcome_video_panel(chat_id, user_id)
    elif action == "admin_theme_preview":
        ui(chat_id, "✨ KD Premium Emoji Bot\n🎉 Animated effect preview\n🎨 Small caps and theme blocks\n✅ One custom emoji per button", cancel_keys("admin_theme"))
    elif action == "admin_set_effect":
        ask(chat_id, user_id, "effect_message", "Send a message with a native Telegram message effect.", back="admin_theme")
    elif action == "admin_set_start_emoji":
        ask(chat_id, user_id, "start_emoji", "Send one premium custom emoji to use for the start popup and reaction.", back="admin_theme")
    elif action == "admin_toggle_effect":
        value = effect_id()
        if value:
            STORE.setting("last_message_effect_id", value)
        STORE.setting("message_effect_id", "" if value else STORE.meta("last_message_effect_id", DEFAULT_EFFECT_ID) or DEFAULT_EFFECT_ID)
        theme_panel(chat_id)
    elif action in {"admin_toggle_theme", "admin_toggle_popup", "admin_toggle_reaction"}:
        key = {"admin_toggle_theme": "quote_theme", "admin_toggle_popup": "start_popup", "admin_toggle_reaction": "start_reaction"}[action]
        STORE.setting(key, "0" if setting_on(key) else "1")
        theme_panel(chat_id)
    elif action == "claim_bonus":
        if require_join(chat_id, user_id):
            success, value = STORE.bonus(user_id)
            if success:
                ui(chat_id, f"🎉 Bonus claimed\n+{value} points\nNext bonus in 24 hours.")
            else:
                hours, remainder = divmod(value, 3600)
                minutes, seconds = divmod(remainder, 60)
                ui(chat_id, f"⏳ Already claimed\nTry again in {hours}h {minutes}m {seconds}s.")
    elif action == "copy_link" or action.startswith("copy_link_"):
        if not STORE.user(user_id):
            raise UserError("Use /start first.")
        link = ref_link(user_id)
        ui(chat_id, f"Your referral link:\n{link}\nTap and hold to copy.", codes=[link])
    elif action == "get_access":
        if not STORE.user(user_id):
            raise UserError("Use /start first.")
        referrals(chat_id, user_id)
    elif action in {"add_photo", "add_video", "no_media", "add_button", "no_button", "back_media", "back_buttons"}:
        if not require_post(chat_id, user_id):
            return
        if action in {"add_photo", "add_video", "no_media"}:
            data = dict(active_prompt(call, {"media_choice"}))
            if action == "no_media":
                button_choice(chat_id, user_id, dict(data, photo_id=None, video_id=None))
            else:
                if u16(data.get("text", "")) > 1024:
                    raise UserError("Caption too long. Choose No Media, or /cancel and shorten the text.")
                stage = "photo" if action == "add_photo" else "video"
                ask(chat_id, user_id, stage, f"Send one {stage}.", data, back="back_media")
        elif action in {"add_button", "no_button"}:
            data = dict(active_prompt(call, {"button_choice"}))
            if action == "add_button":
                ask(chat_id, user_id, "button_name", "Send the button name.", data, back="back_buttons")
            else:
                finish_post(chat_id, user_id, dict(data, btn_name=None, btn_url=None))
        elif action == "back_media":
            media_choice(chat_id, user_id, active_prompt(call, {"photo", "video"}))
        else:
            button_choice(chat_id, user_id, active_prompt(call, {"button_name", "button_url"}))
    elif action.startswith(("post_send:", "post_edit:", "post_preview:")):
        if not require_post(chat_id, user_id):
            return
        verb, post_id = action.split(":", 1)
        data = STORE.post(post_id, user_id)
        if verb == "post_send":
            ask(chat_id, user_id, "post_destination", "Forward a post from the destination channel or send its numeric ID.", {"id": post_id}, back="home")
        elif verb == "post_preview":
            send_post(chat_id, data)
            post_controls(chat_id, data)
        else:
            draft = dict(data, text=data.get("raw_text", data.get("text", data.get("content", ""))), entities=data.get("raw_entities", data.get("entities", [])), edit_id=post_id)
            draft.pop("content", None)
            ask(chat_id, user_id, "post_text", "Send the updated post text, photo or video.\nThen choose media and button options.", draft, back="home")
    elif action.startswith("send_"):
        parts = action.split("_", 2)
        if len(parts) != 3:
            raise UserError("Invalid send action.")
        publish(chat_id, user_id, parts[1], parts[2])
    else:
        raise UserError("This button is no longer available. Use /start.")


def on_callback(call):
    if not call.from_user or not call.message:
        ack(call, "Use /start.")
        return
    if (call.data or "").startswith("admin_") and call.from_user.id != ADMIN_ID:
        ack(call, "Owner only.")
        return
    ack(call)
    chat_id, user_id = call.message.chat.id, call.from_user.id
    invalidate_intro(chat_id, user_id)
    with user_lock(chat_id, user_id):
        try:
            callback_action(call)
        except UserError as error:
            with contextlib.suppress(Exception):
                ui(chat_id, f"❌ {error}")
        except Exception as error:
            log_error("callback handler", error)
            with contextlib.suppress(Exception):
                ui(chat_id, "❌ Action could not be confirmed. Try again or use /cancel.")


def start_health():
    class HealthHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path not in {"/", "/health"}:
                self.send_error(404)
                return
            body = json.dumps({"status": "stopping" if STOP.is_set() else "alive", "users": len(STORE.audience()), "time": datetime.now(timezone.utc).isoformat()}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *args):
            pass
    try:
        server = ThreadingHTTPServer(("0.0.0.0", 8080), HealthHandler)
    except OSError as error:
        log_error("optional health server", error)
        return
    threading.Thread(target=server.serve_forever, name="health", daemon=True).start()


def shutdown(signum=None, frame=None):
    STOP.set()
    BROADCAST_CANCEL.set()
    if BOT is not None:
        BOT.stop_polling()


def main():
    global BOT, STORE, CATALOG, BOT_ME, INTRO_POOL
    setup_logging()
    CATALOG = EmojiCatalog()
    if "--self-test" in sys.argv:
        self_test()
        return
    if TOKEN == "PASTE_BOT_TOKEN_HERE" or not re.fullmatch(r"\d+:[A-Za-z0-9_-]+", TOKEN):
        raise SystemExit("Set TOKEN or BOT_TOKEN first.")
    if ADMIN_ID <= 0:
        raise SystemExit("Set ADMIN_ID or BOT_ADMIN_ID to your positive Telegram user ID.")
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    lock_file = (DATA_DIR / ".kd-emoji.lock").open("a")
    try:
        try:
            import fcntl
            fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise SystemExit("Another bot instance is using this data directory.")
        except ImportError:
            LOG.warning("Instance file locking unavailable on this OS.")
        STORE = Storage(DATA_DIR)
        BOT = telebot.TeleBot(TOKEN, threaded=True, num_threads=8)
        INTRO_POOL = ThreadPoolExecutor(max_workers=4, thread_name_prefix="start-animation")
        BOT.register_message_handler(on_message, content_types=["text", "photo", "video", "document", "animation", "sticker", "audio", "voice", "video_note", "contact", "location", "venue", "poll", "dice"], func=lambda message: True)
        BOT.register_callback_query_handler(on_callback, func=lambda call: True)
        signal.signal(signal.SIGINT, shutdown)
        signal.signal(signal.SIGTERM, shutdown)
        while not STOP.is_set():
            try:
                BOT_ME = tg(BOT.get_me, max_wait=30)
                tg(BOT.remove_webhook, max_wait=30)
                break
            except ApiTelegramException as error:
                if (getattr(error, "result_json", {}) or {}).get("error_code") in {401, 404}:
                    raise SystemExit("Telegram rejected BOT_TOKEN.")
                log_error("startup API", error)
                STOP.wait(5)
            except Exception as error:
                log_error("startup connection", error)
                STOP.wait(5)
        if STOP.is_set():
            return
        CATALOG.initialize()
        with contextlib.suppress(Exception):
            tg(BOT.set_my_commands, [types.BotCommand("start", "Open menu"), types.BotCommand("access", "Check access"), types.BotCommand("cancel", "Cancel current step"), types.BotCommand("send", "Publish saved post"), types.BotCommand("help", "Show help")])
        start_health()
        LOG.info("KD bot @%s ready; owner=%s; users=%s", BOT_ME.username, ADMIN_ID, len(STORE.audience()))
        while not STOP.is_set():
            try:
                BOT.infinity_polling(timeout=30, long_polling_timeout=25, skip_pending=False, allowed_updates=["message", "callback_query"])
            except Exception as error:
                log_error("polling restart", error)
            if not STOP.is_set():
                STOP.wait(5)
    finally:
        shutdown()
        if INTRO_POOL is not None:
            INTRO_POOL.shutdown(wait=True, cancel_futures=True)
        lock_file.close()


def self_test():
    """Run storage and real-handler regression checks without a Telegram token.

    All API calls below go to a local fake. Test data is confined to a fresh
    temporary directory; no production database or account is opened.
    """
    from types import SimpleNamespace
    global BOT, STORE, BOT_ME, ADMIN_ID, CATALOG, INTRO_POOL, OWNER_NAME
    saved_globals = (BOT, STORE, BOT_ME, ADMIN_ID, CATALOG, INTRO_POOL, OWNER_NAME)
    counts = {"checks": 0, "flows": 0}

    def check(condition, message):
        if not condition:
            raise AssertionError(message)
        counts["checks"] += 1

    def rejected(function, description, code=400, parameters=None):
        payload = {"ok": False, "error_code": code, "description": description}
        if parameters is not None:
            payload["parameters"] = parameters
        return ApiTelegramException(function, None, payload)

    class FakeTelegram:
        def __init__(self):
            self.events = []
            self.sequence = 100
            self.joined = True
            self.reject_custom_reaction = True
            self.lock = threading.RLock()

        def message(self, user_id, text=None, kind="text", chat_id=None, message_id=None, **extra):
            payload = {"message_id": message_id or self.sequence + 1, "date": int(time.time()),
                       "chat": {"id": chat_id if chat_id is not None else user_id, "type": "private" if (chat_id or user_id) > 0 else "supergroup"},
                       "from": {"id": user_id, "is_bot": False, "first_name": "Test User"}}
            if text is not None:
                payload["text"] = text
            if kind == "photo":
                payload["photo"] = [{"file_id": "PHOTO_FILE", "file_unique_id": "PHOTO_UNIQUE", "width": 640, "height": 480}]
            elif kind == "video":
                payload["video"] = {"file_id": "VIDEO_FILE", "file_unique_id": "VIDEO_UNIQUE", "width": 640, "height": 480, "duration": 5}
            payload.update(extra)
            return types.Message.de_json(payload)

        def callback(self, user_id, data, chat_id=None, message_id=None):
            target = chat_id if chat_id is not None else user_id
            state = STORE.state(target, user_id)
            chosen_id = message_id or (state["prompt_id"] if state else self.sequence)
            message = self.message(999, "prompt", chat_id=target, message_id=chosen_id)
            return types.CallbackQuery.de_json({"id": secrets.token_hex(4), "chat_instance": "test", "data": data,
                                               "from": {"id": user_id, "is_bot": False, "first_name": "Test User"}, "message": message.json})

        def get_chat(self, target):
            if int(target) > 0:
                return SimpleNamespace(id=int(target), type="private", first_name="Test Owner", last_name="", username=None)
            return SimpleNamespace(id=int(target), type="channel", title="Test Channel", username="test_channel", invite_link=None)

        def get_chat_member(self, target, user_id):
            if user_id == 999 or user_id == ADMIN_ID:
                return SimpleNamespace(status="administrator", can_post_messages=True, can_invite_users=True)
            if user_id == 222:
                return SimpleNamespace(status="administrator" if self.joined else "left", is_member=self.joined)
            return SimpleNamespace(status="member" if self.joined else "left", is_member=self.joined)

