        def create_chat_invite_link(self, target, **kwargs):
            return SimpleNamespace(invite_link="https://t.me/+TEST_INVITE")

        def send(self, kind, chat_id, content, options):
            text = content if kind == "text" else options.get("caption", "")
            entities = entity_dicts(options.get("entities") if kind == "text" else options.get("caption_entities"))
            valid_entities(text, entities)
            check(u16(text) <= (4096 if kind == "text" else 1024), "message/caption budget")
            markup = options.get("reply_markup")
            markup_dict = json.loads(markup.to_json()) if markup else None
            if markup_dict:
                for row in markup_dict.get("inline_keyboard", markup_dict.get("keyboard", [])):
                    for item in row:
                        check(item.get("style") in {None, "primary", "danger", "success"}, "only documented native button styles")
                        if item.get("icon_custom_emoji_id"):
                            check(not emoji.emoji_list(item["text"]), "custom icon is not duplicated in button text")
                        if "callback_data" in item:
                            check(len(item["callback_data"].encode()) <= 64, "callback byte budget")
            with self.lock:
                self.sequence += 1
                self.events.append({"kind": kind, "chat": chat_id, "content": content, "text": text,
                                    "entities": entities, "markup": markup_dict,
                                    "options": options, "id": self.sequence})
                payload = {"message_id": self.sequence, "date": int(time.time()), "chat": {"id": chat_id, "type": "private" if chat_id > 0 else "channel"}, "text": text}
                if options.get("message_effect_id"):
                    payload["effect_id"] = options["message_effect_id"]
                return types.Message.de_json(payload)

        def send_message(self, chat_id, text, **kwargs):
            return self.send("text", chat_id, text, kwargs)

        def send_photo(self, chat_id, photo, **kwargs):
            return self.send("photo", chat_id, photo, kwargs)

        def send_video(self, chat_id, video, **kwargs):
            return self.send("video", chat_id, video, kwargs)

        def delete_message(self, chat_id, message_id):
            self.events.append({"kind": "delete", "chat": chat_id, "id": message_id})
            return True

        def set_message_reaction(self, chat_id, message_id, reaction, **kwargs):
            value = reaction[0].to_dict()
            self.events.append({"kind": "reaction", "reaction": value, "chat": chat_id})
            if value["type"] == "custom_emoji" and self.reject_custom_reaction:
                raise rejected("setMessageReaction", "Bad Request: REACTION_INVALID")
            return True

        def answer_callback_query(self, *args, **kwargs):
            return True

        def copy_message(self, *args, **kwargs):
            self.events.append({"kind": "copy", "chat": args[0]})
            return SimpleNamespace(message_id=123)

